export default async function ({ page, capture, assert }) {
  await page.getByRole('heading', { name: '存储项目' }).waitFor();
  await page.getByRole('button', { name: '开始扫描' }).click();
  await page.getByRole('navigation', { name: '存储类别' }).waitFor();
  const allSegments = await page.locator('.local-storage-bar > span').count();
  assert.ok(allSegments > 1, 'The composition bar is visible');
  const scope = page.getByRole('combobox', { name: '选择存储范围' });
  await scope.click();
  const menu = page.locator('select:open');
  await menu.waitFor();
  await capture('scope-menu');
  await page.getByRole('option', { name: '跨工作区及未知归属' }).click();
  const sharedSegments = await page.locator('.local-storage-bar > span').count();
  assert.ok(sharedSegments > 0 && sharedSegments < allSegments, 'Filtering also updates the bar');
  await scope.click();
  await page.getByRole('option', { name: '全部范围' }).click();
  await page.getByRole('navigation', { name: '存储类别' }).getByRole('button', { name: /^会话/ }).click();
  assert.equal(await page.getByRole('checkbox', { name: '选择 代码审查与改进' }).evaluate(el => getComputedStyle(el).appearance), 'auto', 'Storage selection uses checkboxes rather than switches');
  await page.getByRole('checkbox', { name: '选择 代码审查与改进' }).check();
  await capture('selected');
  await page.getByRole('button', { name: '检查清理影响' }).click();
  const dialog = page.getByRole('dialog', { name: '确认清理所选项目？' });
  await dialog.waitFor();
  assert.ok(await dialog.getByText(/永久删除会话记录/).count());
  const bounds = await dialog.boundingBox(), viewport = page.viewportSize();
  assert.ok(bounds && bounds.x >= 0 && bounds.x + bounds.width <= viewport.width + 1, 'The confirmation fits');
  await capture('review');
  await dialog.getByRole('button', { name: '取消' }).click();
  await dialog.waitFor({ state: 'hidden' });
  await page.evaluate(() => window.__setStorageLocale('en'));
  await page.getByRole('heading', { name: 'Storage items' }).waitFor();
  assert.ok(await page.getByRole('button', { name: 'Review cleanup' }).isVisible());
  assert.equal(await page.locator('.settings-content').evaluate(el => el.scrollWidth <= el.clientWidth + 1), true, 'No horizontal overflow');
  await capture('english');
  const englishScope = page.getByRole('combobox', { name: 'Choose storage scope' });
  await englishScope.focus();
  await page.keyboard.press('ArrowDown');
  const englishMenu = page.locator('select:open');
  await englishMenu.waitFor();
  await capture('english-scope-menu');
  await page.keyboard.press('Escape');
  await englishMenu.waitFor({ state: 'hidden' });
  assert.equal(await englishScope.evaluate(el => el === document.activeElement), true, 'Escape restores focus');
}
